import React, { useEffect, useState } from 'react';
import SearchBarUnified from './components/SearchBarUnified';
import ProductSlider from './components/ProductSlider';
import CategorySlider from './components/CategorySlider';
import { getCategories, getHomeProducts } from './services/api';
import './styles.css';

// Orden fijo (lo estabas manejando en App.js)
const ORDER = ['Gastronomía','Indumentaria','Hogar','Tecnología','Deportes','Belleza'];

// Diccionario opcional nombre → ícono mientras Category no tenga imageUrl en DB
const ICONS = {
  'Gastronomía':  '/icons/gastronomia.png',
  'Indumentaria': '/icons/indumentaria.png',
  'Hogar':        '/icons/hogar.png',
  'Tecnología':   '/icons/tecnologia.png',
  'Deportes':     '/icons/deportes.png',
  'Belleza':      '/icons/belleza.png'
};

export default function App(){
  const [categorias, setCategorias] = useState([]);
  const [productosHome, setProductosHome] = useState([]);

  useEffect(() => {
    (async () => {
      try {
        // 1) Categorías desde BD
        const catsRaw = await getCategories();

        // Orden fijo por nombre (si no existe en ORDER, va al final)
        const catsOrdered = [...catsRaw].sort((a,b) => {
          const ai = ORDER.indexOf(a.name);
          const bi = ORDER.indexOf(b.name);
          return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
        });

        // Inyectar imageUrl (hasta que lo guardes en BD)
        const cats = catsOrdered.map(c => ({
          ...c,
          imageUrl: ICONS[c.name] || '/placeholder-cat.png'
        }));
        setCategorias(cats);

        // 2) Productos destacados/home desde BD
        const prods = await getHomeProducts(12);
        // ProductSlider espera {id, imageUrl}
        const slides = prods.map(p => ({ id: p.id, imageUrl: p.imageUrl || '/placeholder.png' }));
        setProductosHome(slides);
      } catch (e) {
        console.error('Error cargando home:', e);
        setCategorias([]);
        setProductosHome([]);
      }
    })();
  }, []);

  return (
    <div className="page">
      <header className="header">
        <div className="logo">
          <a href="/"><img src="/logo-conecta.png" alt="Conecta Pinamar" /></a>
        </div>
        <SearchBarUnified />
      </header>

      <section>
        <h2 className="title">SOLO POR ESTA SEMANA</h2>
        <ProductSlider id="semana" images={productosHome} />
      </section>

      <section>
        <h2 className="title">CATEGORÍAS</h2>
        <CategorySlider categories={categorias} />
      </section>

      <section>
        <h2 className="title">DESTACADOS</h2>
        <ProductSlider id="destacados" images={productosHome} />
      </section>
    </div>
  );
}
